<?php require_once __DIR__.'/../../includes/admin-check.php';$rows=$pdo->query('SELECT d.created_at,u.nama,m.nama motor,k.kode,k.nama kerusakan FROM diagnosis d JOIN users u ON u.id=d.user_id JOIN motor m ON m.id=d.motor_id LEFT JOIN kerusakan k ON k.id=d.kerusakan_id ORDER BY d.created_at DESC')->fetchAll();?><!doctype html><html lang="id"><meta charset="utf-8"><title>Laporan</title><link rel="stylesheet" href="<?=BASE_URL?>/assets/css/custom.css"><h1>Laporan Diagnosis</h1><table><tr><th>Tanggal</th><th>Pengguna</th><th>Motor</th><th>Kerusakan</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['motor'])?></td><td><?=e(($r['kode']??'').' '.($r['kerusakan']??'Tidak ditemukan'))?></td></tr><?php endforeach?></table><script>window.print()</script></html>